# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ORUÇ İBADETİNİN BİREYSEL VE AHLAKİ KAZANIMLARI</text>\n  <rect x="20" y="48" width="155" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="97" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. Sabır ve İrade</text>\n  <text x="97" y="102" text-anchor="middle" font-size="11" fill="#1e3a8a">• Açlık ve susuzluğa</text>\n  <text x="97" y="120" text-anchor="middle" font-size="11" fill="#1e3a8a">dayanma gücü verir.</text>\n  <text x="97" y="144" text-anchor="middle" font-size="11" fill="#1e3a8a">• Nefsin isteklerini</text>\n  <text x="97" y="162" text-anchor="middle" font-size="11" fill="#1e3a8a">kontrol etmeyi öğretir.</text>\n  <text x="97" y="204" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#2563eb">«Oruç sabrın yarısıdır.»</text>\n\n  <rect x="188" y="48" width="155" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="265" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">2. Şükür Bilinci</text>\n  <text x="265" y="102" text-anchor="middle" font-size="11" fill="#14532d">• Bir yudum suyun ve</text>\n  <text x="265" y="120" text-anchor="middle" font-size="11" fill="#14532d">bir lokma ekmeğin</text>\n  <text x="265" y="138" text-anchor="middle" font-size="11" fill="#14532d">kıymetini hatırlatır.</text>\n  <text x="265" y="162" text-anchor="middle" font-size="11" fill="#14532d">• İsraftan kaçınmayı</text>\n  <text x="265" y="204" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#166534">Nimetlerin değerini bilme</text>\n\n  <rect x="356" y="48" width="155" height="190" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="433" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">3. Empati ve Merhamet</text>\n  <text x="433" y="102" text-anchor="middle" font-size="11" fill="#713f12">• Yoksulların ve</text>\n  <text x="433" y="120" text-anchor="middle" font-size="11" fill="#713f12">muhtaçların çektiği</text>\n  <text x="433" y="138" text-anchor="middle" font-size="11" fill="#713f12">sıkıntıyı bizzat</text>\n  <text x="433" y="156" text-anchor="middle" font-size="11" fill="#713f12">yaşayarak hissettirir.</text>\n  <text x="433" y="204" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#854d0e">Şefkat ve duyarlılık</text>\n\n  <rect x="524" y="48" width="156" height="190" rx="8" fill="#fdf2f8" stroke="#ec4899" stroke-width="1.5"/>\n  <text x="602" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">4. Kötülükten Korunma</text>\n  <text x="602" y="102" text-anchor="middle" font-size="11" fill="#9d174d">• Yalan, dedikodu, öfke</text>\n  <text x="602" y="120" text-anchor="middle" font-size="11" fill="#9d174d">ve kırıcı sözlerden</text>\n  <text x="602" y="138" text-anchor="middle" font-size="11" fill="#9d174d">uzak durmayı sağlar.</text>\n  <text x="602" y="162" text-anchor="middle" font-size="11" fill="#9d174d">• Takva bilinci kazandırır.</text>\n  <text x="602" y="204" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#be185d">«Oruç bir kalkandır.»</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">RAMAZAN AYINDA TOPLUMSAL DAYANIŞMA VE PAYLAŞMA</text>\n  <rect x="25" y="48" width="310" height="190" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="180" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Toplumsal Birlik ve Kardeşlik</text>\n  <text x="180" y="104" text-anchor="middle" font-size="11.5" fill="#155e75">• İftar sofralarında akrabalar, komşular</text>\n  <text x="180" y="122" text-anchor="middle" font-size="11.5" fill="#155e75">ve ihtiyaç sahipleri bir araya gelir.</text>\n  <text x="180" y="148" text-anchor="middle" font-size="11.5" fill="#155e75">• Teravih namazı ve mukabele geleneği</text>\n  <text x="180" y="166" text-anchor="middle" font-size="11.5" fill="#155e75">camilerde cemaat kaynaşmasını artırır.</text>\n  <text x="180" y="194" text-anchor="middle" font-size="11.5" fill="#155e75">• Sıla-i rahim (akraba ziyareti) ve</text>\n  <text x="180" y="212" text-anchor="middle" font-size="11.5" fill="#155e75">bayramlaşma ile kırgınlıklar sona erer.</text>\n\n  <rect x="365" y="48" width="310" height="190" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="520" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Yardımlaşma Kültürümüz</text>\n  <text x="520" y="104" text-anchor="middle" font-size="11.5" fill="#581c87">• İnfak, zekât, fitre ve sadakalarla</text>\n  <text x="520" y="122" text-anchor="middle" font-size="11.5" fill="#581c87">zengin ile yoksul arasında köprü kurulur.</text>\n  <text x="520" y="148" text-anchor="middle" font-size="11.5" fill="#581c87">• İftar çadırları, erzak kolileri ve</text>\n  <text x="520" y="166" text-anchor="middle" font-size="11.5" fill="#581c87">askıda ekmek uygulamaları yaygınlaşır.</text>\n  <text x="520" y="194" text-anchor="middle" font-size="11.5" fill="#581c87">• Osmanlı\'dan kalan «Zimem Defteri»</text>\n  <text x="520" y="212" text-anchor="middle" font-size="11.5" fill="#581c87">(veresiye borcu silme) geleneği yaşatılır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">İNFAK, SADAKA, FİTRE (FITIR SADAKASI) VE FİDYE KARŞILAŞTIRMASI</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="125" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">İnfak ve Sadaka</text>\n  <text x="125" y="100" text-anchor="middle" font-size="11" fill="#1e3a8a">• İnfak: Allah rızası için</text>\n  <text x="125" y="118" text-anchor="middle" font-size="11" fill="#1e3a8a">maldan harcama yapmaktır.</text>\n  <text x="125" y="144" text-anchor="middle" font-size="11" fill="#1e3a8a">• Sadaka: Maddi ve manevi</text>\n  <text x="125" y="162" text-anchor="middle" font-size="11" fill="#1e3a8a">her türlü iyiliktir (tebessüm</text>\n  <text x="125" y="180" text-anchor="middle" font-size="11" fill="#1e3a8a">bile sadakadır).</text>\n  <text x="125" y="212" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#2563eb">Zaman ve miktar sınırı yoktur</text>\n\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Fitre (Fıtır Sadakası)</text>\n  <text x="350" y="100" text-anchor="middle" font-size="11" fill="#14532d">• Ramazan ayına kavuşmanın</text>\n  <text x="350" y="118" text-anchor="middle" font-size="11" fill="#14532d">şükrü olarak verilir.</text>\n  <text x="350" y="144" text-anchor="middle" font-size="11" fill="#14532d">• Hükmü: Vaciptir (nisap</text>\n  <text x="350" y="162" text-anchor="middle" font-size="11" fill="#14532d">miktarı malı olana).</text>\n  <text x="350" y="180" text-anchor="middle" font-size="11" fill="#14532d">• Bayram namazından önce</text>\n  <text x="350" y="212" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#166534">Ailedeki her birey için verilir</text>\n\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#fff7ed" stroke="#f97316" stroke-width="1.5"/>\n  <text x="575" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#c2410c">Fidye</text>\n  <text x="575" y="100" text-anchor="middle" font-size="11" fill="#9a3412">• Yaşlılık veya iyileşme</text>\n  <text x="575" y="118" text-anchor="middle" font-size="11" fill="#9a3412">ümidi olmayan kronik</text>\n  <text x="575" y="136" text-anchor="middle" font-size="11" fill="#9a3412">hastalık sebebiyle hiç</text>\n  <text x="575" y="154" text-anchor="middle" font-size="11" fill="#9a3412">oruç tutamayanların</text>\n  <text x="575" y="172" text-anchor="middle" font-size="11" fill="#9a3412">verdiği bedeldir.</text>\n  <text x="575" y="212" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#c2410c">Tutulamayan her gün için 1 fitre</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
